require 'config.php';require 'includes/functions.php';require_admin();
$users=$pdo->query("SELECT * FROM users WHERE registration_status IN ('pending_review','paid') ORDER BY registration_paid_at DESC, payment_submitted_at DESC, created_at DESC")->fetchAll();$pageTitle='Registration payments';require 'includes/header.php';?>
<div class="section-head"><div><div class="eyebrow">Administration</div><h1>Registration payments</h1></div><a class="btn btn-light" href="admin-dashboard.php">Dashboard</a></div><div class="panel"><p>Registration status is updated automatically after PayFast's server notification is validated. This page is for viewing, not manually confirming payments.</p><?php if(!$users):?><p class="muted">No registration payments yet.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Member</th><th>Contact</th><th>Member code</th><th>Status</th><th>Paid at</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['full_name'])?><br><span class="small muted"><?=e($u['email'])?></span></td><td><?=e($u['phone'])?></td><td><?=e($u['member_code']??'Not assigned yet')?></td><td><span class="status <?=e($u['registration_status'])?>"><?=e($u['registration_status'])?></span></td><td><?=e($u['registration_paid_at']??'—')?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div><?php require 'includes/footer.php';?>